import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry gelu_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .s32 n_elements
)
{
    .reg .pred  %p0;
    .reg .b32   %r<6>;
    .reg .b64   %rd<6>;
    .reg .f32   %f<13>;

    // Load parameters
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.s32 %r2, [n_elements];
    cvt.u32.s32  %r3, %r2;

    // Compute linear thread index: idx = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32  %r0, %tid.x;
    mov.u32  %r1, %ntid.x;
    mov.u32  %r4, %ctaid.x;
    mad.lo.s32 %r5, %r4, %r1, %r0;

    // Bounds check
    setp.ge.u32 %p0, %r5, %r3;
    @%p0 bra DONE;

    // Compute byte offsets
    mul.wide.u32 %rd3, %r5, 4;
    add.s64 %rd4, %rd1, %rd3; // in_ptr + offset
    add.s64 %rd5, %rd2, %rd3; // out_ptr + offset

    // Load input
    ld.global.f32 %f0, [%rd4];        // x

    // Constants
    mov.f32 %f1, 0.5;                 // 0.5
    mov.f32 %f2, 1.0;                 // 1.0
    mov.f32 %f3, 0.044715;            // 0.044715
    mov.f32 %f4, 0.797884583;         // sqrt(2/pi) ~ 0.797884583

    // x^3
    mul.rn.f32 %f5, %f0, %f0;         // x^2
    mul.rn.f32 %f6, %f5, %f0;         // x^3

    // t = x + 0.044715 * x^3
    fma.rn.f32 %f7, %f3, %f6, %f0;

    // u = sqrt(2/pi) * t
    mul.rn.f32 %f8, %f4, %f7;

    // v = tanh(u)
    tanh.approx.f32 %f9, %f8;

    // w = 1 + v
    add.f32 %f10, %f2, %f9;

    // y = 0.5 * x * w
    mul.rn.f32 %f11, %f1, %f0;        // 0.5 * x
    mul.rn.f32 %f12, %f11, %f10;      // y

    // Store output
    st.global.f32 [%rd5], %f12;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("gelu_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor):
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Input must be float32"
        assert x.is_contiguous(), "Input must be contiguous"
        out = torch.empty(x.shape, device=x.device, dtype=x.dtype)

        n = x.numel()
        block_x = 256
        grid_x = (n + block_x - 1) // block_x

        module = _get_ptx_module()
        module.launch(
            "gelu_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, i32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

